('la-befana','La Befana','minion','Goodpart',NULL,NULL,'The Menagerie','{"slug":"la-befana","name":"La Befana","team":"minion","ability":"Each night, pick a player. You learn what is in their present, and once per game, may change it to a boon or bane. [+1 or -1 Outsider]","creator":"Goodpart","appearsIn":"The Menagerie","quote":"La Befana vien di notte / Con le scarpe tutte rotte / Con le toppe alla sottana / Viva viva La Befana!","lede":"","howToRun":[],"tips":[],"bluffing":[],"fighting":[],"examples":[],"firstNight":30,"firstNightReminder":"La Befana chooses a player. Show them the present that player has. They may give you a thumbs up or thumbs down to change it to a boon or bane.","otherNight":30,"otherNightReminder":"La Befana chooses a player. Show them the present that player has. They may give you a thumbs up or thumbs down to change it to a boon or bane.","reminders":[],"setup":true,"image":"https://menagerie.towerrangers.net/images/coale.png","curata":false,"imageAlt":"https://menagerie.towerrangers.net/images/coalg.png"}','published','the-menagerie/la-befana',datetime('now'),datetime('now')),
('krampus','Krampus','demon','Goodpart',NULL,NULL,'The Menagerie','{"slug":"krampus","name":"Krampus","team":"demon","ability":"Each night, pick a player: their boon becomes a bane. Each night*, a player might die.","creator":"Goodpart","appearsIn":"The Menagerie","quote":"Warst nicht brav, drum hoppla-hopp, kommt das Krampus im galopp.","lede":"","howToRun":[],"tips":[],"bluffing":[],"fighting":[],"examples":[],"firstNight":32,"firstNightReminder":"Krampus chooses a player.","otherNight":37,"otherNightReminder":"Krampus chooses a player.","reminders":["Dead","Dead","Dead"],"setup":false,"image":"https://menagerie.towerrangers.net/images/krampe.png","curata":false,"imageAlt":"https://menagerie.towerrangers.net/images/krampg.png"}','published','the-menagerie/krampus',datetime('now'),datetime('now')),
('santa-claus','Santa Claus','loric','Goodpart',NULL,NULL,'The Menagerie','{"slug":"santa-claus","name":"Santa Claus","team":"loric","ability":"On Night 1, each player gives a present to a unique player. Boons given by good players help the good team, and vice versa. On the night the dead equals or outnumbers the living, all players open their presents.","creator":"Goodpart","appearsIn":"The Menagerie","quote":"He sees you when you''re sleeping, he knows when you''re awake, he knows if you''ve been bad or good, so be good for goodness sake!","lede":"","howToRun":[],"tips":[],"bluffing":[],"fighting":[],"examples":[],"firstNight":1.5,"firstNightReminder":"Wake each player and ask them to choose a player. If that player has already been chosen, prompt them to choose again. If there is an odd number of players, one player receives a present from the Storyteller, and learn this.","otherNight":1.5,"otherNightReminder":"Go around the Grimoire and apply the effects of presents, either publicly or privately.","reminders":[],"setup":false,"image":"https://menagerie.towerrangers.net/images/santa.png","curata":false}','published','the-menagerie/santa-claus',datetime('now'),datetime('now'));